const navToggle=document.querySelector(".nav-toggle"),navMenu=document.querySelector(".nav-menu"),year=document.querySelector("[data-year]"),quoteForms=document.querySelectorAll(".quote-card,.quote-form"),videoLoads=document.querySelectorAll(".video-load"),WEBHOOK_URL="https://hook.us2.make.com/28cg2mxxubr5tqvuagcyg2nh4aj1sq3j";if(year){year.textContent=new Date().getFullYear()}if(navToggle&&navMenu){navToggle.addEventListener("click",()=>{const isOpen=navMenu.classList.toggle("is-open");navToggle.setAttribute("aria-expanded",String(isOpen))});navMenu.addEventListener("click",(event)=>{if(event.target instanceof HTMLAnchorElement){navMenu.classList.remove("is-open");navToggle.setAttribute("aria-expanded","false")}})}quoteForms.forEach((quoteForm)=>{quoteForm.addEventListener("submit",async(event)=>{const formNote=quoteForm.querySelector("[data-form-note]"),submitBtn=quoteForm.querySelector("button[type=submit]");event.preventDefault();if(submitBtn)submitBtn.disabled=true;if(formNote){formNote.textContent="Sending your request…";formNote.setAttribute("role","status")}const data={name:quoteForm.querySelector("[name=name]")?.value||"",phone:quoteForm.querySelector("[name=phone]")?.value||"",email:quoteForm.querySelector("[name=email]")?.value||"",project:quoteForm.querySelector("[name=project]")?.value||"",message:quoteForm.querySelector("[name=message]")?.value||"",submittedAt:new Date().toISOString(),source:window.location.href};try{const res=await fetch(WEBHOOK_URL,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(data)});if(!res.ok)throw new Error("Network response was not ok");if(formNote){formNote.textContent="Thanks! We received your request and you’ll hear from us shortly. For urgent questions call (440) 668-4065."}quoteForm.reset()}catch{if(formNote){formNote.textContent="Something went wrong. Please call us at (440) 668-4065 and we’ll get you a quote right away."}}finally{if(submitBtn)submitBtn.disabled=false}})});videoLoads.forEach((videoLoad)=>{videoLoad.addEventListener("click",()=>{const videoSrc=videoLoad.getAttribute("data-video-src"),videoPoster=videoLoad.getAttribute("data-video-poster");if(!videoSrc)return;const video=document.createElement("video");video.controls=true;video.autoplay=true;video.preload="metadata";if(videoPoster)video.poster=videoPoster;video.innerHTML=`<source src="${videoSrc}" type="video/mp4">Your browser does not support the video tag.`;videoLoad.replaceWith(video)})});
